import os
from typing import Any, Dict, List, Optional

from google.cloud import firestore


class FirestoreDocumentStore:
    def __init__(self, project_id: Optional[str] = None, database: Optional[str] = None) -> None:
        client_kwargs: Dict[str, Any] = {}
        if project_id:
            client_kwargs["project"] = project_id
        if database:
            client_kwargs["database"] = database
        self.client = firestore.Client(**client_kwargs)

    def query_by_field_value(
        self,
        collection_name: str,
        field_name: str,
        field_value: Any,
        limit: Optional[int] = None,
    ) -> List[Dict[str, Any]]:
        query = self.client.collection(collection_name).where(filter=firestore.FieldFilter(field_name, "==", field_value))
        if limit is not None:
            query = query.limit(limit)

        results: List[Dict[str, Any]] = []
        for doc in query.stream():
            item = doc.to_dict()
            item["_id"] = doc.id
            results.append(item)
        return results

    def query_by_partition_key(
        self,
        collection_name: str,
        partition_field: str,
        partition_value: Any,
        limit: Optional[int] = None,
    ) -> List[Dict[str, Any]]:
        return self.query_by_field_value(
            collection_name=collection_name,
            field_name=partition_field,
            field_value=partition_value,
            limit=limit,
        )


def query_documents(
    collection_name: str,
    *,
    field_name: Optional[str] = None,
    field_value: Any = None,
    partition_key_name: Optional[str] = None,
    partition_key_value: Any = None,
    limit: Optional[int] = None,
    project_id: Optional[str] = None,
    database: Optional[str] = None,
) -> List[Dict[str, Any]]:
    store = FirestoreDocumentStore(project_id=project_id, database=database)

    if partition_key_name is not None:
        return store.query_by_partition_key(
            collection_name=collection_name,
            partition_field=partition_key_name,
            partition_value=partition_key_value,
            limit=limit,
        )

    if field_name is None:
        raise ValueError("Either field_name/field_value or partition_key_name/partition_key_value must be provided.")

    return store.query_by_field_value(
        collection_name=collection_name,
        field_name=field_name,
        field_value=field_value,
        limit=limit,
    )


if __name__ == "__main__":
    os.environ.setdefault("GOOGLE_APPLICATION_CREDENTIALS", os.environ.get("GOOGLE_APPLICATION_CREDENTIALS", ""))
